const original = $('F07 맞춤 메시지 생성 시작').first().json;
const row = $json ?? {};

const day = (value) =>
  value ? String(value).slice(0, 10) : null;


// 프로모션 본문 정리
const text = String(row.promotion_text ?? '')
  .replace(/^프로모션 ID:.*$/gm, '')
  .trim();


const lines = [];

if (row.file_name) {
  lines.push(`프로모션명: ${row.file_name}`);
}

if (day(row.valid_from) && day(row.valid_until)) {
  lines.push(
    `적용 기간: ${day(row.valid_from)} ~ ${day(row.valid_until)}`
  );
}

if (text) {
  lines.push(text);
}


return {
  json: {
    ...original,

    promotion_context:
      text
        ? lines.join('\n')
        : null,

    rag_status:
      text
        ? 'FOUND'
        : 'NOT_FOUND'
  }
};

// F07_맞춤 메시지 생성_서브 → 노드 "메시지 생성 컨텍스트 구성" 의 코드 전체 (이슈 #28)
//
// 바뀐 점: 직원이 [지금 발송]으로 미리 보내는 문자일 때(message_data.send_now === true)
// 오늘 날짜와 기준일까지 남은 일수를 send_timing 으로 넘겨, 문자가 지금 시점에 맞게 쓰이게 한다.
// 자동 발송에서는 이 값이 오지 않으므로 지금까지와 똑같이 동작한다.

const data = $json;
const m = data.message_data ?? {};

let messageContext;

switch (m.schedule_type) {

  case 'contract':
    messageContext = {
      type: 'contract',
      reason: m.contact_reason ?? null,
      contract_end_date: m.contract_end_date ?? null,
      current_device: m.current_device ?? null,
      current_plan: m.current_plan ?? null
    };
    break;

  case 'reconsultation':
    messageContext = {
      type: 'reconsultation',
      reason: m.contact_reason ?? null,
      consultation_summary: m.consultation_summary ?? null,
      current_device: m.current_device ?? null,
      current_plan: m.current_plan ?? null,
      interests: m.interests ?? null
    };
    break;

  case 'promotion':
    messageContext = {
      type: 'promotion',
      reason: m.contact_reason ?? null,
      promotion_context: data.promotion_context ?? null,
      rag_status: data.rag_status ?? 'NOT_FOUND'
    };
    break;

  default:
    messageContext = {
      type: 'unknown',
      reason: m.contact_reason ?? null
    };
}

// 예정일보다 먼저 보내는 문자의 시점 정보. 없으면 넣지 않는다.
if (m.send_now === true) {
  messageContext.send_timing = {
    today: m.today ?? null,
    reference_label: m.reference_label ?? null,
    reference_date: m.reference_date ?? null,
    days_until_reference:
      typeof m.days_until_reference === 'number' ? m.days_until_reference : null
  };
}

return {
  json: {
    schedule_id: data.schedule_id ?? null,
    customer_id: m.customer_id ?? null,
    customer_name: m.customer_name ?? null,
    phone: m.phone ?? null,
    schedule_type: m.schedule_type ?? null,
    message_context: messageContext
  }
};

