const original = $('메시지 생성 컨텍스트 구성').first().json;

// Structured Output Parser 결과
const messageText = String(
  $json.output?.message_text ?? ''
).trim();

// 빈 메시지 확인
const hasMessage = messageText.length > 0;

// 내부 시스템 정보 노출 방어
const containsInternalData =
  messageText.includes('document_id') ||
  messageText.includes('message_context') ||
  messageText.includes('promotion_context') ||
  messageText.includes('rag_status');

const generationSuccess =
  hasMessage &&
  !containsInternalData;

let generationError = null;

if (!hasMessage) {
  generationError = 'EMPTY_MESSAGE';
}
else if (containsInternalData) {
  generationError = 'INTERNAL_DATA_EXPOSED';
}

return {
  json: {
    schedule_id: original.schedule_id ?? null,
    customer_id: original.customer_id ?? null,
    phone: original.phone ?? null,

    generation_success: generationSuccess,

    message_text: generationSuccess
      ? messageText
      : null,

    generation_error: generationError
  }
};
